#!/usr/bin/env node
/**
 * Fidelity check of the replayed legacy schema against the generated
 * `src/integrations/supabase/types.ts` (Phase 2 spec §D.5; proposed D-131).
 *
 * `types.ts` is regenerated by Lovable from the live database, so it is the
 * best record of what exists live. After the legacy replay (before any
 * build-out file) every public table, view, column and function that
 * `types.ts` names must exist in the replayed database; a miss fails unless
 * `supabase/tests/harness/replay.json` lists it under `fidelityExceptions`
 * with a reason. Nullability and type-class differences, objects the database
 * has but `types.ts` does not, enum differences, function argument-name
 * differences and stale exceptions are warnings.
 *
 * Library: `parseTypesTs`, `querySchema`, `diffFidelity`. CLI:
 *   node scripts/db/fidelity.mjs --psql "-h <socket dir> -p <port> -U postgres -d storm"
 *        [--types src/integrations/supabase/types.ts] [--replay supabase/tests/harness/replay.json]
 *        [--psql-bin <path to psql>] [--json]
 * Exit 0: no unexplained miss; 1: misses; 3: usage error.
 */
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import ts from 'typescript';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');

const nameOf = (node) => {
  if (!node) return '';
  if (ts.isIdentifier(node) || ts.isPrivateIdentifier(node)) return node.text;
  if (ts.isStringLiteral(node) || ts.isNumericLiteral(node)) return node.text;
  return node.getText();
};

const memberType = (literal, name) => {
  if (!literal || !ts.isTypeLiteralNode(literal)) return null;
  const member = literal.members.find((m) => ts.isPropertySignature(m) && nameOf(m.name) === name);
  return member?.type ?? null;
};

const isNullType = (t) => t.kind === ts.SyntaxKind.LiteralType && t.literal.kind === ts.SyntaxKind.NullKeyword;

/** The TS type class of a Row column: string | number | boolean | json | enum:<name> | array:<class> | unknown. */
export function tsTypeClass(typeNode) {
  let t = typeNode;
  while (t && ts.isParenthesizedTypeNode(t)) t = t.type;
  if (!t) return 'unknown';
  if (ts.isUnionTypeNode(t)) {
    const parts = t.types.filter((p) => !isNullType(p));
    if (parts.length === 1) return tsTypeClass(parts[0]);
    if (parts.every((p) => ts.isLiteralTypeNode(p) && ts.isStringLiteral(p.literal))) return 'string';
    return 'unknown';
  }
  if (ts.isArrayTypeNode(t)) return `array:${tsTypeClass(t.elementType)}`;
  if (ts.isLiteralTypeNode(t) && ts.isStringLiteral(t.literal)) return 'string';
  if (ts.isIndexedAccessTypeNode(t)) {
    const text = t.getText().replace(/\s+/g, '');
    const m = text.match(/\["Enums"\]\["([^"]+)"\]$/);
    return m ? `enum:${m[1]}` : 'unknown';
  }
  if (ts.isTypeReferenceNode(t)) return nameOf(t.typeName) === 'Json' ? 'json' : 'unknown';
  switch (t.kind) {
    case ts.SyntaxKind.StringKeyword:
      return 'string';
    case ts.SyntaxKind.NumberKeyword:
      return 'number';
    case ts.SyntaxKind.BooleanKeyword:
      return 'boolean';
    default:
      return 'unknown';
  }
}

const isNullable = (typeNode) => {
  let t = typeNode;
  while (t && ts.isParenthesizedTypeNode(t)) t = t.type;
  return !!t && ts.isUnionTypeNode(t) && t.types.some(isNullType);
};

function relations(literal) {
  const out = new Map();
  if (!literal || !ts.isTypeLiteralNode(literal)) return out;
  for (const m of literal.members) {
    if (!ts.isPropertySignature(m) || !m.type) continue;
    const row = memberType(m.type, 'Row');
    const columns = new Map();
    if (row && ts.isTypeLiteralNode(row)) {
      for (const c of row.members) {
        if (!ts.isPropertySignature(c) || !c.type) continue;
        columns.set(nameOf(c.name), { tsType: tsTypeClass(c.type), nullable: isNullable(c.type), text: c.type.getText() });
      }
    }
    out.set(nameOf(m.name), { columns });
  }
  return out;
}

function functionOverloads(typeNode) {
  let t = typeNode;
  while (t && ts.isParenthesizedTypeNode(t)) t = t.type;
  const variants = t && ts.isUnionTypeNode(t) ? t.types : [t];
  const overloads = [];
  for (const v of variants) {
    if (!v || !ts.isTypeLiteralNode(v)) continue;
    const args = memberType(v, 'Args');
    const list = [];
    if (args && ts.isTypeLiteralNode(args)) {
      for (const a of args.members) if (ts.isPropertySignature(a)) list.push({ name: nameOf(a.name), optional: !!a.questionToken });
    }
    overloads.push({ args: list });
  }
  return overloads;
}

/**
 * Parses `types.ts` source: `{ tables, views, functions, enums }` of
 * `Database.public` (Maps keyed by name).
 */
export function parseTypesTs(source, fileName = 'types.ts') {
  const sf = ts.createSourceFile(fileName, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  let database = null;
  sf.forEachChild((node) => {
    if (ts.isTypeAliasDeclaration(node) && node.name.text === 'Database') database = node.type;
  });
  if (!database) throw new Error(`${fileName}: no "export type Database" found`);
  const pub = memberType(database, 'public');
  if (!pub) throw new Error(`${fileName}: Database has no "public" schema`);
  const functions = new Map();
  const fnLiteral = memberType(pub, 'Functions');
  if (fnLiteral && ts.isTypeLiteralNode(fnLiteral)) {
    for (const m of fnLiteral.members) if (ts.isPropertySignature(m) && m.type) functions.set(nameOf(m.name), { overloads: functionOverloads(m.type) });
  }
  const enums = new Map();
  const enumLiteral = memberType(pub, 'Enums');
  if (enumLiteral && ts.isTypeLiteralNode(enumLiteral)) {
    for (const m of enumLiteral.members) {
      if (!ts.isPropertySignature(m) || !m.type) continue;
      const parts = ts.isUnionTypeNode(m.type) ? m.type.types : [m.type];
      enums.set(
        nameOf(m.name),
        parts.filter((p) => ts.isLiteralTypeNode(p) && ts.isStringLiteral(p.literal)).map((p) => p.literal.text),
      );
    }
  }
  return { tables: relations(memberType(pub, 'Tables')), views: relations(memberType(pub, 'Views')), functions, enums };
}

/** The type class of a database column, from its pg_type category and name (comparable with `tsTypeClass`). */
export function dbTypeClass({ typname, category, elemName = null, elemCategory = null }) {
  const one = (name, cat) => {
    if (cat === 'E') return `enum:${name}`;
    if (['json', 'jsonb'].includes(name)) return 'json';
    if (cat === 'B') return 'boolean';
    if (cat === 'N') return 'number';
    if (['S', 'D', 'T', 'V'].includes(cat)) return 'string';
    if (['uuid', 'bytea', 'citext'].includes(name)) return 'string';
    return 'unknown';
  };
  if (category === 'A') return `array:${one(elemName, elemCategory)}`;
  return one(typname, category);
}

const SCHEMA_SQL = {
  relations: `
    SELECT c.relname,
           CASE WHEN c.relkind IN ('r', 'p', 'f') THEN 'table' ELSE 'view' END,
           a.attname,
           CASE WHEN a.attnotnull THEN 'f' ELSE 't' END,
           t.typname, t.typcategory, coalesce(et.typname, ''), coalesce(et.typcategory, '')
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
      JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
      JOIN pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_type et ON et.oid = t.typelem AND t.typcategory = 'A'
     WHERE c.relkind IN ('r', 'p', 'f', 'v', 'm')
     ORDER BY c.relname, a.attnum`,
  emptyRelations: `
    SELECT c.relname, CASE WHEN c.relkind IN ('r', 'p', 'f') THEN 'table' ELSE 'view' END
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
     WHERE c.relkind IN ('r', 'p', 'f', 'v', 'm')`,
  functions: `
    SELECT p.proname,
           coalesce((SELECT string_agg(coalesce(u.nm, ''), ',' ORDER BY u.i)
                       FROM unnest(coalesce(p.proargnames, array_fill(''::text, ARRAY[coalesce(array_length(p.proargmodes, 1), p.pronargs)])))
                            WITH ORDINALITY AS u(nm, i)
                      WHERE coalesce(p.proargmodes[u.i]::text, 'i') IN ('i', 'b', 'v')), ''),
           p.pronargdefaults::text,
           CASE WHEN p.prorettype = 'trigger'::regtype THEN 't' ELSE 'f' END
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
     WHERE p.prokind IN ('f', 'p')
     ORDER BY 1`,
  enums: `
    SELECT t.typname, e.enumlabel
      FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace AND n.nspname = 'public'
      JOIN pg_enum e ON e.enumtypid = t.oid
     ORDER BY t.typname, e.enumsortorder`,
};

/**
 * Reads the public schema through `query(sql) -> Promise<string[][]>`:
 * `{ tables, views, functions, enums }` shaped like `parseTypesTs`.
 */
export async function querySchema(query) {
  const tables = new Map();
  const views = new Map();
  for (const [rel, kind] of await query(SCHEMA_SQL.emptyRelations)) (kind === 'table' ? tables : views).set(rel, { columns: new Map() });
  for (const [rel, kind, col, nullable, typname, category, elemName, elemCategory] of await query(SCHEMA_SQL.relations)) {
    const target = kind === 'table' ? tables : views;
    if (!target.has(rel)) target.set(rel, { columns: new Map() });
    target.get(rel).columns.set(col, { dbType: dbTypeClass({ typname, category, elemName, elemCategory }), nullable: nullable === 't', typname });
  }
  const functions = new Map();
  for (const [name, args, defaults, isTrigger] of await query(SCHEMA_SQL.functions)) {
    if (!functions.has(name)) functions.set(name, { overloads: [], trigger: true });
    const entry = functions.get(name);
    const names = args === '' ? [] : args.split(',');
    entry.overloads.push({ args: names.map((n) => ({ name: n })), defaults: Number(defaults) });
    if (isTrigger !== 't') entry.trigger = false;
  }
  const enums = new Map();
  for (const [name, label] of await query(SCHEMA_SQL.enums)) enums.set(name, [...(enums.get(name) ?? []), label]);
  return { tables, views, functions, enums };
}

const typeCompatible = (tsType, dbType) => {
  if (tsType === 'unknown' || dbType === 'unknown') return true;
  if (tsType === dbType) return true;
  // types.ts writes some enum columns as plain string unions
  if (tsType === 'string' && dbType.startsWith('enum:')) return true;
  if (tsType.startsWith('array:') && dbType.startsWith('array:')) return typeCompatible(tsType.slice(6), dbType.slice(6));
  return false;
};

/**
 * Compares `types.ts` (`expected`) with the database (`actual`).
 * `exceptions` is `fidelityExceptions` of replay.json. Returns
 * `{ misses, unexplained, explained, warnings, counts }`; the check passes
 * when `unexplained` is empty.
 */
export function diffFidelity(expected, actual, exceptions = {}) {
  const misses = [];
  const warnings = [];
  const used = new Set();
  const exceptionFor = (kind, name) => {
    const map = exceptions?.[kind] ?? {};
    if (Object.prototype.hasOwnProperty.call(map, name)) {
      used.add(`${kind}:${name}`);
      return map[name];
    }
    return null;
  };
  const miss = (kind, name, detail) => misses.push({ kind, name, detail, reason: exceptionFor(kind === 'column' ? 'columns' : `${kind}s`, name) });

  const compareRelations = (kind, exp, act, other) => {
    for (const [rel, { columns }] of exp) {
      const found = act.get(rel) ?? other.get(rel);
      if (!found) {
        miss(kind, rel, `${kind} ${rel} is in types.ts but not in the replayed database`);
        continue;
      }
      if (!act.has(rel)) warnings.push({ kind: 'relation_kind', name: rel, detail: `types.ts lists ${rel} as a ${kind}; the database has it as a ${kind === 'table' ? 'view' : 'table'}` });
      for (const [col, want] of columns) {
        const got = found.columns.get(col);
        if (!got) {
          miss('column', `${rel}.${col}`, `column ${rel}.${col} is in types.ts but not in the replayed database`);
          continue;
        }
        // The generator writes `unknown` (inet, tsvector, …) without `| null`: its nullability is not shown.
        if (kind === 'table' && act.has(rel) && want.tsType !== 'unknown' && want.nullable !== got.nullable) {
          warnings.push({ kind: 'nullability', name: `${rel}.${col}`, detail: `types.ts ${want.nullable ? 'nullable' : 'not null'}, database ${got.nullable ? 'nullable' : 'not null'}` });
        }
        if (!typeCompatible(want.tsType, got.dbType)) {
          warnings.push({ kind: 'type', name: `${rel}.${col}`, detail: `types.ts ${want.text} (${want.tsType}), database ${got.typname} (${got.dbType})` });
        }
      }
      for (const col of found.columns.keys()) {
        if (!columns.has(col)) warnings.push({ kind: 'extra_column', name: `${rel}.${col}`, detail: `database column ${rel}.${col} is not in types.ts` });
      }
    }
  };
  compareRelations('table', expected.tables, actual.tables, actual.views);
  compareRelations('view', expected.views, actual.views, actual.tables);

  for (const [name, { overloads }] of expected.functions) {
    const found = actual.functions.get(name);
    if (!found) {
      miss('function', name, `function ${name} is in types.ts but not in the replayed database`);
      continue;
    }
    for (const o of overloads) {
      const want = o.args.map((a) => a.name).sort().join(',');
      const match = found.overloads.some((d) => d.args.map((a) => a.name).sort().join(',') === want);
      if (!match) {
        warnings.push({
          kind: 'function_args',
          name,
          detail: `types.ts args (${want || 'none'}) match no database overload (${found.overloads.map((d) => d.args.map((a) => a.name).join(',') || 'none').join(' | ')})`,
        });
      }
    }
  }

  for (const [name, labels] of expected.enums) {
    const got = actual.enums.get(name);
    if (!got) warnings.push({ kind: 'enum', name, detail: `enum ${name} is in types.ts but not in the database` });
    else {
      const missing = labels.filter((l) => !got.includes(l));
      if (missing.length) warnings.push({ kind: 'enum', name, detail: `enum ${name} lacks ${missing.join(', ')}` });
    }
  }

  const extraTables = [...actual.tables.keys()].filter((t) => !expected.tables.has(t) && !expected.views.has(t));
  const extraViews = [...actual.views.keys()].filter((v) => !expected.views.has(v) && !expected.tables.has(v));
  const extraFunctions = [...actual.functions].filter(([n, f]) => !f.trigger && !expected.functions.has(n)).map(([n]) => n);
  for (const t of extraTables) warnings.push({ kind: 'extra_table', name: t, detail: `database table ${t} is not in types.ts` });
  for (const v of extraViews) warnings.push({ kind: 'extra_view', name: v, detail: `database view ${v} is not in types.ts` });
  for (const f of extraFunctions) warnings.push({ kind: 'extra_function', name: f, detail: `database function ${f} is not in types.ts` });

  for (const [kind, map] of Object.entries(exceptions ?? {})) {
    for (const name of Object.keys(map ?? {})) {
      if (!used.has(`${kind}:${name}`)) warnings.push({ kind: 'stale_exception', name: `${kind}.${name}`, detail: `fidelityExceptions.${kind}["${name}"] matches no miss: remove it` });
    }
  }

  const unexplained = misses.filter((m) => !m.reason);
  const explained = misses.filter((m) => m.reason);
  const countKinds = (list) => list.reduce((acc, w) => ({ ...acc, [w.kind]: (acc[w.kind] ?? 0) + 1 }), {});
  return {
    misses,
    unexplained,
    explained,
    warnings,
    counts: {
      typesTables: expected.tables.size,
      typesViews: expected.views.size,
      typesFunctions: expected.functions.size,
      dbTables: actual.tables.size,
      dbViews: actual.views.size,
      dbFunctions: actual.functions.size,
      unexplained: unexplained.length,
      explained: explained.length,
      warnings: countKinds(warnings),
    },
  };
}

/** One-line summary of a fidelity result. */
export function fidelitySummary(result) {
  const c = result.counts;
  const w = Object.entries(c.warnings)
    .map(([k, n]) => `${k} ${n}`)
    .join(', ');
  return `types.ts ${c.typesTables} tables / ${c.typesViews} views / ${c.typesFunctions} functions; ${c.unexplained} unexplained miss(es), ${c.explained} explained; warnings: ${w || 'none'}`;
}

function cli(argv) {
  const opts = { psql: null, types: join(ROOT, 'src/integrations/supabase/types.ts'), replay: join(ROOT, 'supabase/tests/harness/replay.json'), psqlBin: 'psql', json: false };
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    const value = () => {
      const v = argv[i + 1];
      if (!v) throw new Error(`${a} needs a value`);
      i += 1;
      return v;
    };
    if (a === '--psql') opts.psql = value();
    else if (a === '--types') opts.types = resolve(value());
    else if (a === '--replay') opts.replay = resolve(value());
    else if (a === '--psql-bin') opts.psqlBin = value();
    else if (a === '--json') opts.json = true;
    else throw new Error(`unknown flag ${a}`);
  }
  if (!opts.psql) throw new Error('--psql "<connection args>" is required');
  return opts;
}

async function main() {
  let opts;
  try {
    opts = cli(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`fidelity: ${err.message}\nUsage: node scripts/db/fidelity.mjs --psql "-h <socket dir> -p <port> -U postgres -d storm" [--types <types.ts>] [--replay <replay.json>] [--psql-bin <psql>] [--json]\n`);
    process.exit(3);
  }
  const connection = opts.psql.split(/\s+/).filter(Boolean);
  const query = async (sql) => {
    const out = spawnSync(opts.psqlBin, ['-X', '-A', '-t', '-q', '-F', '\x1f', '-R', '\x1e', '-v', 'ON_ERROR_STOP=1', ...connection, '-c', sql], { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 });
    if (out.status !== 0) throw new Error(`psql failed: ${out.stderr || out.error?.message}`);
    return out.stdout
      .split('\x1e')
      .map((r) => r.replace(/^\n+|\n+$/g, ''))
      .filter(Boolean)
      .map((r) => r.split('\x1f'));
  };
  const expected = parseTypesTs(readFileSync(opts.types, 'utf8'), opts.types);
  const replay = JSON.parse(readFileSync(opts.replay, 'utf8'));
  const result = diffFidelity(expected, await querySchema(query), replay.fidelityExceptions ?? {});
  if (opts.json) process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
  else {
    for (const m of result.unexplained) process.stdout.write(`MISS ${m.kind} ${m.name}: ${m.detail}\n`);
    for (const m of result.explained) process.stdout.write(`explained ${m.kind} ${m.name}: ${m.reason}\n`);
    for (const w of result.warnings) process.stdout.write(`warning ${w.kind} ${w.name}: ${w.detail}\n`);
    process.stdout.write(`${fidelitySummary(result)}\n`);
  }
  process.exit(result.unexplained.length ? 1 : 0);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  main().catch((err) => {
    process.stderr.write(`fidelity: ${err.stack ?? err}\n`);
    process.exit(1);
  });
}
